1	// dispatch-plan.mjs — pre-enforcement dispatch planning and roster enforcement.
2	//
3	// The plan is observational data for R11-B. It is elicited before any
4	// enforcement text is shown, with tools disabled, then the execution call
5	// resumes the same coordinator session. Enforcement is deliberately narrower
6	// than topology execution: it can require coordinator→office dispatches, but it
7	// cannot make Claude Code subagents call one another or prove typed edges fired.
8	
9	import fs from "node:fs";
10	import path from "node:path";
11	import { spawn } from "node:child_process";
12	
13	export const PLAN_MARKER_OPEN = "[CIVAGENT_DISPATCH_PLAN]";
14	export const PLAN_MARKER_CLOSE = "[/CIVAGENT_DISPATCH_PLAN]";
15	export const PLAN_STATES = Object.freeze({
16	  PARSED_NONEMPTY: "parsed_nonempty",
17	  PARSED_EMPTY: "parsed_empty",
18	  PARSE_FAILED: "parse_failed",
19	});
20	
21	const OFFICE_ID_RE = /^[A-Za-z0-9_.-]+$/;
22	
23	export function listAgentOffices(agentsJson) {
24	  try {
25	    const parsed = typeof agentsJson === "string" ? JSON.parse(agentsJson) : agentsJson;
26	    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return [];
27	    return Object.keys(parsed).filter((id) => OFFICE_ID_RE.test(id));
28	  } catch {
29	    return [];
30	  }
31	}
32	
33	export function buildPlanPrompt({ task, offices }) {
34	  const officeLines = offices.length
35	    ? offices.map((office) => `- ${office}`).join("\n")
36	    : "(none)";
37	  return `You are about to handle the task below. Before doing any task work,
38	truthfully record which available offices, if any, you would choose to call.
39	
40	Task:
41	${task}
42	
43	Available offices:
44	${officeLines}
45	
46	This is a measurement of your unforced intent. Choosing zero offices is valid.
47	Choosing fewer offices is valid. Do not add offices merely to fill the plan.
48	Do not execute the task and do not call an office yet.
49	
50	Return exactly one JSON object between the marker lines:
51	${PLAN_MARKER_OPEN}
52	{"dispatches":[{"office":"office-id","order":1,"responsibility":"specific responsibility"}]}
53	${PLAN_MARKER_CLOSE}
54	
55	Use {"dispatches":[]} when you would call no office. Every office must be from
56	the available list; order values must be unique consecutive integers starting
57	at 1. Output no other marker block.`;
58	}
59	
60	function markerCount(text, marker) {
61	  let count = 0;
62	  let from = 0;
63	  while (true) {
64	    const at = text.indexOf(marker, from);
65	    if (at < 0) return count;
66	    count += 1;
67	    from = at + marker.length;
68	  }
69	}
70	
71	export function validateDispatches(value, allowedOffices = null) {
72	  if (!value || typeof value !== "object" || Array.isArray(value)) {
73	    return { ok: false, error: "plan must be a JSON object" };
74	  }
75	  if (!Array.isArray(value.dispatches)) {
76	    return { ok: false, error: "plan.dispatches must be an array" };
77	  }
78	
79	  const allowed = Array.isArray(allowedOffices) ? new Set(allowedOffices) : null;
80	  const dispatches = [];
81	  const orders = new Set();
82	  for (let i = 0; i < value.dispatches.length; i += 1) {
83	    const step = value.dispatches[i];
84	    if (!step || typeof step !== "object" || Array.isArray(step)) {
85	      return { ok: false, error: `dispatches[${i}] must be an object` };
86	    }
87	    const office = step.office;
88	    const order = step.order;
89	    const responsibility = step.responsibility;
90	    if (typeof office !== "string" || !OFFICE_ID_RE.test(office)) {
91	      return { ok: false, error: `dispatches[${i}].office is not a bare office id` };
92	    }
93	    if (allowed && !allowed.has(office)) {
94	      return { ok: false, error: `dispatches[${i}].office is not available: ${office}` };
95	    }
96	    if (!Number.isInteger(order) || order < 1 || orders.has(order)) {
97	      return { ok: false, error: `dispatches[${i}].order must be a unique positive integer` };
98	    }
99	    if (typeof responsibility !== "string" || responsibility.trim().length === 0) {
100	      return { ok: false, error: `dispatches[${i}].responsibility must be non-empty` };
101	    }
102	    orders.add(order);
103	    dispatches.push({ office, order, responsibility: responsibility.trim() });
104	  }
105	  dispatches.sort((a, b) => a.order - b.order);
106	  for (let i = 0; i < dispatches.length; i += 1) {
107	    if (dispatches[i].order !== i + 1) {
108	      return { ok: false, error: "order values must be consecutive starting at 1" };
109	    }
110	  }
111	  return { ok: true, dispatches };
112	}
113	
114	export function parsePlanOutput(output, allowedOffices = null) {
115	  const raw = typeof output === "string" ? output : "";
116	  if (markerCount(raw, PLAN_MARKER_OPEN) !== 1 ||
117	      markerCount(raw, PLAN_MARKER_CLOSE) !== 1) {
118	    return {
119	      status: PLAN_STATES.PARSE_FAILED,
120	      dispatches: null,
121	      error: "expected exactly one dispatch-plan marker block",
122	    };
123	  }
124	  const open = raw.indexOf(PLAN_MARKER_OPEN);
125	  const close = raw.indexOf(PLAN_MARKER_CLOSE);
126	  if (close <= open) {
127	    return {
128	      status: PLAN_STATES.PARSE_FAILED,
129	      dispatches: null,
130	      error: "dispatch-plan markers are out of order",
131	    };
132	  }
133	  let decoded;
134	  try {
135	    decoded = JSON.parse(raw.slice(open + PLAN_MARKER_OPEN.length, close).trim());
136	  } catch (error) {
137	    return {
138	      status: PLAN_STATES.PARSE_FAILED,
139	      dispatches: null,
140	      error: `dispatch-plan JSON parse failed: ${error.message}`,
141	    };
142	  }
143	  const validated = validateDispatches(decoded, allowedOffices);
144	  if (!validated.ok) {
145	    return {
146	      status: PLAN_STATES.PARSE_FAILED,
147	      dispatches: null,
148	      error: validated.error,
149	    };
150	  }
151	  return {
152	    status: validated.dispatches.length
153	      ? PLAN_STATES.PARSED_NONEMPTY
154	      : PLAN_STATES.PARSED_EMPTY,
155	    dispatches: validated.dispatches,
156	    error: null,
157	  };
158	}
159	
160	export function buildPlanArgs({ agentsJson, prompt, sessionId }) {
161	  return [
162	    "--agents", agentsJson,
163	    "--tools", "",
164	    "--output-format", "text",
165	    "--session-id", sessionId,
166	    "-p", prompt,
167	  ];
168	}
169	
170	export function runPlanCall({
171	  command,
172	  args,
173	  env,
174	  timeoutMs = 120_000,
175	  spawnImpl = spawn,
176	}) {
177	  return new Promise((resolve) => {
178	    let settled = false;
179	    let stdout = "";
180	    let stderr = "";
181	    let child;
182	    let timer = null;
183	    const finish = (result) => {
184	      if (settled) return;
185	      settled = true;
186	      if (timer) clearTimeout(timer);
187	      resolve({ stdout, stderr, ...result });
188	    };
189	    try {
190	      child = spawnImpl(command, args, { env, stdio: ["ignore", "pipe", "pipe"] });
191	    } catch (error) {
192	      resolve({ stdout, stderr, code: null, signal: null, error: error.message });
193	      return;
194	    }
195	    child.stdout?.on("data", (chunk) => { stdout += chunk; });
196	    child.stderr?.on("data", (chunk) => { stderr += chunk; });
197	    child.on("error", (error) => finish({ code: null, signal: null, error: error.message }));
198	    child.on("close", (code, signal) => finish({
199	      code,
200	      signal,
201	      error: code === 0 ? null : `plan backend exited ${code}${signal ? ` (${signal})` : ""}`,
202	    }));
203	    timer = setTimeout(() => {
204	      child.kill("SIGKILL");
205	      finish({ code: null, signal: "SIGKILL", error: `plan backend timed out after ${timeoutMs}ms` });
206	    }, timeoutMs);
207	  });
208	}
209	
210	export function officesWithIncomingEdges(topology) {
211	  const nodeIds = new Set(
212	    (Array.isArray(topology?.nodes) ? topology.nodes : [])
213	      .map((node) => node?.id)
214	      .filter((id) => typeof id === "string" && OFFICE_ID_RE.test(id)),
215	  );
216	  const required = [];
217	  const seen = new Set();
218	  for (const edge of Array.isArray(topology?.edges) ? topology.edges : []) {
219	    const office = edge?.to;
220	    if (!nodeIds.has(office) || seen.has(office)) continue;
221	    seen.add(office);
222	    required.push(office);
223	  }
224	  return required.sort();
225	}
226	
227	export function loadRequiredOffices(regimeDir) {
228	  const topologyPath = path.join(regimeDir, "topology.json");
229	  try {
230	    const topology = JSON.parse(fs.readFileSync(topologyPath, "utf8"));
231	    return { ok: true, requiredOffices: officesWithIncomingEdges(topology), error: null };
232	  } catch (error) {
233	    return { ok: false, requiredOffices: [], error: `cannot load topology: ${error.message}` };
234	  }
235	}
236	
237	export function buildEnforcementInstruction(requiredOffices) {
238	  if (!requiredOffices.length) {
239	    return "\n\nEXPERIMENTAL DISPATCH REQUIREMENT:\nNo office has an incoming declared edge; no office dispatch is required.";
240	  }
241	  return `\n\nEXPERIMENTAL DISPATCH REQUIREMENT:
242	After the unforced plan above was recorded, this arm entered the enforced
243	condition. During execution you MUST use the subagent dispatch tool to call
244	each office below at least once, passing the id EXACTLY as written as the
245	tool's subagent_type argument:
246	${requiredOffices.map((office) => `- subagent_type: "${office}"`).join("\n")}
247	
248	These ids come from this arm's own declared topology and are defined in the
249	agent set this session was started with. Do NOT substitute a built-in agent
250	such as "general-purpose" or "Explore" and describe the office in the task text
251	instead: a dispatch to a built-in agent is not a dispatch to that office, and
252	the run is recorded as having exercised no topology. Complete the task after
253	those dispatches. Do not merely say that an office was called.`;
254	}
255	
256	// REMOVED as an evidence source. This used to scan rendered text for
257	// "[→ office]" tokens and was the basis for both enforcement and participation.
258	// A model that never called a subagent could print those two strings in ordinary
259	// prose and obtain enforcement_passed plus participation_observed with
260	// officeTurnCount 0 — i.e. manufacture the very precondition E2 uses to decide
261	// which arms are eligible for the quality comparison. Dispatch evidence now
262	// comes only from tool_use content items carrying a real subagent_type
263	// (see engine/v5/run-v5.mjs executionDispatches). The renderer still writes
264	// "[→ office]" lines for humans; they carry no evidential weight.
265	
266	export function evaluateEnforcement({
267	  requested,
268	  topologyLoaded = true,
269	  topologyError = null,
270	  requiredOffices = [],
271	  dispatchedOffices = [],
272	}) {
273	  const dispatched = [...new Set(dispatchedOffices)].sort();
274	  if (!requested) {
275	    return {
276	      status: "not_requested",
277	      requiredOffices: [],
278	      dispatchedOffices: dispatched,
279	      missingOffices: [],
280	      attempts: 0,
281	      basis: "declared_topology_nodes_with_incoming_edges",
282	    };
283	  }
284	  if (!topologyLoaded) {
285	    return {
286	      status: "enforcement_failed",
287	      requiredOffices: [],
288	      dispatchedOffices: dispatched,
289	      missingOffices: [],
290	      attempts: 1,
291	      error: topologyError || "topology unavailable",
292	      basis: "declared_topology_nodes_with_incoming_edges",
293	    };
294	  }
295	  const required = [...new Set(requiredOffices)].sort();
296	  const present = new Set(dispatched);
297	  const missing = required.filter((office) => !present.has(office));
298	  return {
299	    status: missing.length ? "enforcement_failed" : "enforcement_passed",
300	    requiredOffices: required,
301	    dispatchedOffices: dispatched,
302	    missingOffices: missing,
303	    attempts: 1,
304	    basis: "declared_topology_nodes_with_incoming_edges",
305	  };
306	}
