53	// ── seeded PRNG (mulberry32) ────────────────────────────────────────────────
54	
55	export function mulberry32(seed) {
56	  let s = seed | 0;
57	  return function next() {
58	    s = s + 0x6D2B79F5 | 0;
59	    let t = Math.imul(s ^ s >>> 15, 1 | s);
60	    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
61	    return ((t ^ t >>> 14) >>> 0) / 4294967296;
62	  };
63	}
64	
65	// Fisher–Yates shuffle with a provided random function.
66	function shuffle(arr, rand) {
67	  const a = [...arr];
68	  for (let i = a.length - 1; i > 0; i--) {
69	    const j = Math.floor(rand() * (i + 1));
70	    [a[i], a[j]] = [a[j], a[i]];
71	  }
72	  return a;
73	}
74	
75	// Pick a random element from an array.
76	function pick(arr, rand) {
77	  return arr[Math.floor(rand() * arr.length)];
78	}
