62	  const { matches } = hcPaths(home);
63	  const out = []; // [{ matchId, regime, status, skillPath, ts }]
64	  if (!fs.existsSync(matches)) return out;
65	  for (const id of fs.readdirSync(matches)) {
66	    const dir = path.join(matches, id);
67	    const metaPath = path.join(dir, "meta.json");
68	    const eventsPath = path.join(dir, "events.jsonl");
69	    if (!fs.existsSync(eventsPath)) continue;
70	    let regime = null;
71	    try { regime = readJson(metaPath).regime ?? null; } catch { /* tolerate */ }
72	    for (const ev of readJsonl(eventsPath)) {
