8	/**
9	 * MechanismEngine — orchestrates all V6 constitutional mechanisms.
10	 * 
11	 * Usage:
12	 *   const engine = new MechanismEngine(eventLog, ccProcess, allowedMechanisms);
13	 *   engine.process(chunk);          // feed each stdout chunk
14	 *   engine.getStats();              // { vetoes, impeachments, edicts }
15	 *   engine.reset();                 // reset per-turn state
16	 */
17	export class MechanismEngine {
18	  constructor(eventLog, ccProcess, allowedMechanisms = ['VETO', 'IMPEACH', 'EDICT']) {
19	    this.allowed = new Set(allowedMechanisms.map(m => m.toUpperCase()));
20	    this.context = {
21	      vetoTriggered: false,
22	      vetoImmunity: false,
23	      edictTriggered: false,
24	      impeachments: new Set(),
25	      log: eventLog,
26	      ccProcess: ccProcess,
27	    };
28	    // Stats for analytics
29	    this._stats = { vetoes: 0, impeachments: 0, edicts: 0 };
30	  }
31	
32	  /**
33	   * Process a text chunk from agent output (legacy API — no provenance gating).
34	   * Kept backward-compatible for existing tests and callers that don't pass
35	   * structured provenance. Production code in run-v5.mjs uses processStructured().
36	   */
37	  process(chunk) {
38	    const fired = { veto: false, impeach: false, edict: false };
39	    const chunkText = typeof chunk === "string" ? chunk : String(chunk ?? "");
40	
41	    if (this.allowed.has('EDICT') && checkEdict(chunkText, this.context)) {
42	      fired.edict = true;
43	      this._stats.edicts++;
44	    }
45	
46	    if (this.allowed.has('IMPEACH') && checkImpeach(chunkText, this.context)) {
47	      fired.impeach = true;
48	      this._stats.impeachments++;
49	    }
50	
51	    if (this.allowed.has('VETO') && checkVeto(chunkText, this.context)) {
52	      fired.veto = true;
53	      this._stats.vetoes++;
54	    }
55	
56	    return fired;
57	  }
58	
59	  /**
60	   * Process a text chunk WITH provenance information. This is the primary API
61	   * called by run-v5.mjs.
62	   *
63	   * Provenance gates:
64	   *   1. `actor` must be non-null. Null actors (unparseable lines, system
65	   *      messages without attribution) are REJECTED.
66	   *   2. `messageRole`, when present, must be "assistant". User-role messages
67	   *      are REJECTED. A null messageRole (legacy plain-text backend without
68	   *      stream-json) is ALLOWED for backward compatibility.
69	   *   3. `contentItems` must not contain any `tool_result` items. Tool results
70	   *      carry untrusted external content that can contain marker injection.
71	   *
72	   * @param {{ text: string, actor: string|null, messageRole: string|null,
73	   *          contentItems: Array<{type: string}> }} chunk
74	   * @returns {{ veto: boolean, impeach: boolean, edict: boolean }}
75	   */
76	  processStructured({ text, actor, messageRole, contentItems }) {
77	    const fired = { veto: false, impeach: false, edict: false };
78	
79	    // Gate 1: must have an actor (null = unknown origin → reject).
80	    if (typeof actor !== "string" || actor.length === 0) {
81	      return fired;
82	    }
83	
84	    // Gate 2: if messageRole is present, it must be "assistant".
85	    // null messageRole = legacy plain-text backend → allowed.
86	    if (messageRole !== null && messageRole !== undefined && messageRole !== "assistant") {
87	      return fired;
88	    }
89	
90	    // Gate 3: must not contain tool_result content items.
91	    const items = Array.isArray(contentItems) ? contentItems : [];
92	    const hasToolResult = items.some((item) => item?.type === "tool_result");
93	    if (hasToolResult) {
94	      return fired;
95	    }
96	
97	    const chunkText = typeof text === "string" ? text : String(text ?? "");
98	
99	    if (this.allowed.has("EDICT") && checkEdict(chunkText, this.context)) {
100	      fired.edict = true;
101	      this._stats.edicts++;
102	    }
103	
104	    if (this.allowed.has("IMPEACH") && checkImpeach(chunkText, this.context)) {
105	      fired.impeach = true;
106	      this._stats.impeachments++;
107	    }
108	
109	    if (this.allowed.has("VETO") && checkVeto(chunkText, this.context)) {
110	      fired.veto = true;
111	      this._stats.vetoes++;
112	    }
113	
114	    return fired;
115	  }
116	
117	  /**
118	   * Reset per-turn mechanism state (e.g., between debate rounds).
119	   * Keeps cumulative stats and impeachment history.
120	   */
121	  resetTurn() {
122	    this.context.vetoTriggered = false;
123	    this.context.edictTriggered = false;
124	    this.context.vetoImmunity = false;
125	  }
126	
127	  /** Get cumulative mechanism statistics. */
128	  getStats() {
129	    return { ...this._stats };
130	  }
131	
132	  /** Get the list of impeached targets so far. */
133	  getImpeachments() {
134	    return [...this.context.impeachments];
135	  }
136	
137	  /** Check if a specific mechanism is allowed for this regime. */
138	  isAllowed(mechanism) {
139	    return this.allowed.has(mechanism.toUpperCase());
140	  }
141	}
